package com.salesforce.androidsdk.mobilesync.target
import android.util.Pair
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.filters.SmallTest
import com.salesforce.androidsdk.mobilesync.manager.SyncManagerTestCase
import com.salesforce.androidsdk.mobilesync.util.BriefcaseObjectInfo
import com.salesforce.androidsdk.mobilesync.util.Constants
import com.salesforce.androidsdk.mobilesync.util.SyncState.MergeMode
import com.salesforce.androidsdk.rest.RestRequest
import org.json.JSONObject
import org.junit.After
import org.junit.Assert
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import java.util.Locale

@RunWith(AndroidJUnit4::class) @SmallTest
class BriefcaseSyncDownTargetTest : SyncManagerTestCase() {
    @Before override fun setUp() { super.setUp(); createAccountsSoup(); createContactsSoup() }
    @After override fun tearDown() { dropAccountsSoup(); dropContactsSoup(); cleanRecordsOnServer(); super.tearDown() }
    private fun cleanRecordsOnServer() { deleteRecordsByCriteriaFromServer(Constants.ACCOUNT, " Name like 'BriefcaseTest_%' AND CreatedById = '${restClient.clientInfo.userId}'"); deleteRecordsByCriteriaFromServer(Constants.CONTACT, " LastName like 'BriefcaseTest_%' AND CreatedById = '${restClient.clientInfo.userId}'") }

    @Test fun testStartFetchNoMaxTimeStamp() { val numberAccounts = 12; val accounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); Assert.assertEquals("Wrong number of accounts created", numberAccounts, accounts.size); val target = BriefcaseSyncDownTarget(listOf(BriefcaseObjectInfo(ACCOUNTS_SOUP, Constants.ACCOUNT, listOf(Constants.NAME, Constants.DESCRIPTION)))); val records = target.startFetch(syncManager, 0)!!; Assert.assertEquals(numberAccounts, records.length()); for (i in 0 until records.length()) { val record = records.getJSONObject(i); val id = record.getString(Constants.ID); Assert.assertEquals(accounts[id], record.getString(Constants.NAME)) } }
    @Test fun testStartFetchWithMaxTimeStamp() { val numberAccounts = 6; val oldAccounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); val request = RestRequest.getRequestForQuery(apiVersion, "SELECT Max(SystemModStamp) FROM Account WHERE Name like 'BriefcaseTest_%'"); val responseJson = restClient.sendSync(request).asJSONObject(); val maxTimeStamp = Constants.TIMESTAMP_FORMAT.parse(responseJson.getJSONArray(Constants.RECORDS).getJSONObject(0).getString("expr0"))!!.time; Thread.sleep(1000); val newAccounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); val accountIds = getIdsOnServer(Constants.ACCOUNT, " Name like 'BriefcaseTest_%' AND CreatedById = '${restClient.clientInfo.userId}'"); Assert.assertEquals(numberAccounts * 2, accountIds.size); val target = BriefcaseSyncDownTarget(listOf(BriefcaseObjectInfo(ACCOUNTS_SOUP, Constants.ACCOUNT, listOf(Constants.NAME, Constants.DESCRIPTION)))); val records = target.startFetch(syncManager, maxTimeStamp)!!; Assert.assertEquals(numberAccounts, records.length()); for (i in 0 until records.length()) { val record = records.getJSONObject(i); Assert.assertEquals(newAccounts[record.getString(Constants.ID)], record.getString(Constants.NAME)) } }
    @Test fun testSyncDownFetchingOneObjectType() { trySyncDownFetchingOneObjectType(12, 500, 1) }
    @Test fun testSyncDownFetchingOneObjectTypeWithMultipleRetrieveCalls() { trySyncDownFetchingOneObjectType(12, 2, 6) }
    @Test fun testCleanGhostsOneObjectType() { val numberAccounts = 4; val accounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); val accountIds = accounts.keys.toTypedArray(); val target = BriefcaseSyncDownTarget(listOf(BriefcaseObjectInfo(ACCOUNTS_SOUP, Constants.ACCOUNT, listOf(Constants.NAME, Constants.DESCRIPTION)))); val syncId = trySyncDown(MergeMode.LEAVE_IF_CHANGED, target, ACCOUNTS_SOUP, accounts.size, 1, null); checkDbExist(ACCOUNTS_SOUP, accountIds, Constants.ID); deleteRecordsByIdOnServer(listOf(accountIds[0], accountIds[1]), Constants.ACCOUNT); val localAccounts = createAccountsLocally(arrayOf("local-1", "local-2")); tryCleanResyncGhosts(syncId); checkDbDeleted(ACCOUNTS_SOUP, arrayOf(accountIds[0], accountIds[1]), Constants.ID); checkDbExist(ACCOUNTS_SOUP, arrayOf(accountIds[2], accountIds[3]), Constants.ID); checkDbExist(ACCOUNTS_SOUP, arrayOf(localAccounts[0].getString(Constants.ID), localAccounts[1].getString(Constants.ID)), Constants.ID) }
    @Test fun testSyncDownFetchingTwoObjectTypes() { trySyncDownFetchingTwoObjectTypes(12, 12, 500, 1) }
    @Test fun testSyncDownFetchingTwoObjectTypesWithMultipleRetrieveCalls() { trySyncDownFetchingTwoObjectTypes(12, 12, 3, 8) }
    @Test fun testCleanGhostsTwoObjectTypes() { val result = trySyncDownFetchingTwoObjectTypes(4, 4, 500, 1); val accountIds = result.first.first; val contactIds = result.first.second; val syncId = result.second; deleteRecordsByIdOnServer(listOf(accountIds[0], accountIds[1]), Constants.ACCOUNT); deleteRecordsByIdOnServer(listOf(contactIds[2], contactIds[3]), Constants.CONTACT); val localAccounts = createAccountsLocally(arrayOf("local-1", "local-2")); val localAccountId = localAccounts[0].getString(Constants.ID); val localContacts = createContactsForAccountsLocally(2, localAccountId)[localAccountId]!!; tryCleanResyncGhosts(syncId); checkDbDeleted(ACCOUNTS_SOUP, arrayOf(accountIds[0], accountIds[1]), Constants.ID); checkDbDeleted(CONTACTS_SOUP, arrayOf(contactIds[2], accountIds[3]), Constants.ID); checkDbExist(ACCOUNTS_SOUP, arrayOf(accountIds[2], accountIds[3]), Constants.ID); checkDbExist(CONTACTS_SOUP, arrayOf(contactIds[0], contactIds[1]), Constants.ID); checkDbExist(ACCOUNTS_SOUP, arrayOf(localAccounts[0].getString(Constants.ID), localAccounts[1].getString(Constants.ID)), Constants.ID); checkDbExist(CONTACTS_SOUP, arrayOf(localContacts[0].getString(Constants.ID), localContacts[1].getString(Constants.ID)), Constants.ID) }
    @Test fun testIdsToSkip() { val result = trySyncDownFetchingTwoObjectTypes(4, 4, 500, 1); val accountIds = result.first.first; val contactIds = result.first.second; val syncId = result.second; val target = syncManager.getSyncStatus(syncId)!!.target as BriefcaseSyncDownTarget; var idsToSkip = target.getIdsToSkip(syncManager, ""); Assert.assertTrue(idsToSkip.isEmpty()); deleteRecordsLocally(ACCOUNTS_SOUP, accountIds[0], accountIds[3]); deleteRecordsLocally(CONTACTS_SOUP, contactIds[1], contactIds[2]); idsToSkip = target.getIdsToSkip(syncManager, ""); Assert.assertEquals(4, idsToSkip.size); Assert.assertTrue(idsToSkip.contains(accountIds[0])); Assert.assertTrue(idsToSkip.contains(accountIds[3])); Assert.assertTrue(idsToSkip.contains(contactIds[1])); Assert.assertTrue(idsToSkip.contains(contactIds[2])) }

    override fun createRecordName(objectType: String): String = String.format(Locale.US, "BriefcaseTest_%s_%d", objectType, System.nanoTime())
    protected fun trySyncDownFetchingOneObjectType(numberAccounts: Int, countIdsPerRetrieve: Int, expectedNumberFetches: Int) { val accounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); val accountIds = accounts.keys.toTypedArray(); val target = BriefcaseSyncDownTarget(listOf(BriefcaseObjectInfo(ACCOUNTS_SOUP, Constants.ACCOUNT, listOf(Constants.NAME, Constants.DESCRIPTION))), countIdsPerRetrieve); trySyncDown(MergeMode.LEAVE_IF_CHANGED, target, ACCOUNTS_SOUP, accounts.size, expectedNumberFetches, null); checkDbExist(ACCOUNTS_SOUP, accountIds, Constants.ID) }
    protected fun trySyncDownFetchingTwoObjectTypes(numberAccounts: Int, numberContacts: Int, countIdsPerRetrieve: Int, expectedNumberFetches: Int): Pair<Pair<Array<String>, Array<String>>, Long> { val accounts = createRecordsOnServer(numberAccounts, Constants.ACCOUNT); val accountIds = accounts.keys.toTypedArray(); val contacts = createRecordsOnServer(numberAccounts, Constants.CONTACT); val contactIds = contacts.keys.toTypedArray(); val target = BriefcaseSyncDownTarget(listOf(BriefcaseObjectInfo(ACCOUNTS_SOUP, Constants.ACCOUNT, listOf(Constants.NAME, Constants.DESCRIPTION)), BriefcaseObjectInfo(CONTACTS_SOUP, Constants.CONTACT, listOf(Constants.LAST_NAME))), countIdsPerRetrieve); val syncId = trySyncDown(MergeMode.LEAVE_IF_CHANGED, target, ACCOUNTS_SOUP, accounts.size + contacts.size, expectedNumberFetches, null); checkDbExist(ACCOUNTS_SOUP, accountIds, Constants.ID); checkDbExist(CONTACTS_SOUP, contactIds, Constants.ID); return Pair(Pair(accountIds, contactIds), syncId) }
}
